#include<bits/stdc++.h>using namespace std; int main(){    int t;    cin >> t;    while(t--)    {        int n;        cin >> n;        string s;        cin >> s;        int mina=-1,maxa=-1;        for(int i=0;i<s.size();i++)        {            if(s[i] == 'B')            {                mina = i;                break;            }        }        for(int j=s.size()-1;j>=0;j--)        {            if(s[j] == 'B')            {                maxa = j;                break;            }        }        if(mina == -1) cout << 0 << endl;        else cout << maxa-mina+1 << endl;     }}